using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// The record types that are (almost) only a reflection blob: REFL (and SUNP's RDIF) are Reflection objects, with the
// FormIDs inside them as FormLinks. One whole record of each type from Starfield.esm, both readers, written back byte for byte.
public class ReflectionRecordTests
{
    private static void WritesBack(IStarfieldMajorRecordGetter rec, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => rec.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // ATM_Fog_None (046F59:Starfield.esm)
    private const string FogNoneHex = "";

    [Fact]
    public void FogNone()
    {
        foreach (var rec in ReadBoth<IFogVolumeGetter>(Record("FOGV", Hex(FogNoneHex)), f => FogVolume.CreateFromBinary(f), (s, p) => FogVolumeBinaryOverlay.FogVolumeFactory(s, p)))
        {
            rec.Reflection.ShouldHaveFormIds();
            rec.Reflection.RootObject().Class.Name.ShouldBe("BGSFogVolumeForm");
            WritesBack(rec, FogNoneHex);
        }
    }

    // SunPresetTypeB9 (13422D:Starfield.esm), a diff against SunPresetTypeBTemplate (0E671C:Starfield.esm)
    private const string SunPresetTypeB9Hex = "";

    [Fact]
    public void SunPresetTypeB9()
    {
        foreach (var rec in ReadBoth<ISunPresetGetter>(Record("SUNP", Hex(SunPresetTypeB9Hex)), f => SunPreset.CreateFromBinary(f), (s, p) => SunPresetBinaryOverlay.SunPresetFactory(s, p)))
        {
            rec.Reflection.ShouldBeNull();
            rec.ReflectionDiff.ShouldHaveFormIds(0x0E671C);
            rec.ReflectionDiff.RootObject().IsDiff.ShouldBeTrue();
            WritesBack(rec, SunPresetTypeB9Hex);
        }
    }

