    // ForceDataWindNone (3D2490:Starfield.esm): its falloff curve pointer is null (FormID 0), written back as 0
    private const string WindNoneHex = "";

    [Fact]
    public void WindNone()
    {
        foreach (var rec in ReadBoth<IForceDataGetter>(Record("FORC", Hex(WindNoneHex)), f => ForceData.CreateFromBinary(f), (s, p) => ForceDataBinaryOverlay.ForceDataFactory(s, p)))
        {
            rec.Reflection.ShouldHaveFormIds(0);
            rec.Reflection.RootObject().Class.Name.ShouldBe("BGSForceData");
            rec.Reflection!.FormLinks.Single().IsNull.ShouldBeTrue();
            WritesBack(rec, WindNoneHex);
        }
    }

